"""UTC storage and Python localization, including SQL generated by admin filters."""
from datetime import datetime, timedelta, timezone as dt_timezone
from unittest.mock import patch
from zoneinfo import ZoneInfo

from django.contrib import admin
from django.contrib.auth import get_user_model
from django.db import connection
from django.test import RequestFactory, TestCase, override_settings
from django.test.utils import CaptureQueriesContext
from django.urls import reverse
from django.utils import timezone

from core.models import Announcement


@override_settings(SECURE_SSL_REDIRECT=False, TIME_ZONE='Europe/Moscow', USE_TZ=True)
class DateTimeTests(TestCase):
    def assert_no_timezone_sql(self, queries):
        for query in queries:
            self.assertNotIn('CONVERT_TZ', query['sql'].upper())

    def test_utc_storage_and_round_trip(self):
        local = datetime(2026, 1, 1, 0, 30, tzinfo=ZoneInfo('Europe/Moscow'))
        item = Announcement.objects.create(title='UTC', text='Text', published_at=local)
        with connection.cursor() as cursor:
            cursor.execute('SELECT published_at FROM core_announcement WHERE id = %s', [item.pk])
            self.assertEqual(cursor.fetchone()[0], datetime(2025, 12, 31, 21, 30))
        item.refresh_from_db()
        self.assertEqual(connection.timezone_name, 'UTC')
        self.assertEqual(item.published_at.utcoffset(), timedelta(0))
        self.assertEqual(timezone.localtime(item.published_at), local)
        self.assertTrue(timezone.is_aware(item.created_at))
        self.assertTrue(timezone.is_aware(item.updated_at))

    def test_admin_form_interprets_local_time(self):
        model_admin = admin.site._registry[Announcement]
        form_class = model_admin.get_form(RequestFactory().get('/'))
        with timezone.override('Europe/Moscow'):
            form = form_class(data={
                'title': 'Local input', 'text': 'Text',
                'published_at_0': '2026-01-01', 'published_at_1': '00:30:00',
            })
            self.assertTrue(form.is_valid(), form.errors)
            item = form.save()
        item.refresh_from_db()
        self.assertEqual(item.published_at, datetime(2025, 12, 31, 21, 30, tzinfo=dt_timezone.utc))

    def test_admin_date_filters_and_facets_at_calendar_boundaries(self):
        user = get_user_model().objects.create_superuser('date-admin', password='test')
        model_admin = admin.site._registry[Announcement]
        for month in (1, 12):
            local_now = datetime(2026, month, 1, 0, 30, tzinfo=ZoneInfo('Europe/Moscow'))
            with self.subTest(month=month), timezone.override('Europe/Moscow'):
                Announcement.objects.all().delete()
                midnight = local_now.replace(hour=0, minute=0)
                for value in (midnight - timedelta(microseconds=1), midnight,
                              midnight + timedelta(days=1) - timedelta(microseconds=1),
                              midnight + timedelta(days=1)):
                    Announcement.objects.create(title=str(value), text='Text', published_at=value)
                with patch('django.contrib.admin.filters.timezone.now', return_value=local_now):
                    self.client.force_login(user)
                    response = self.client.get(reverse('admin:core_announcement_changelist'))
                    self.assertEqual(response.status_code, 200)
                    date_filter = next(f for f in response.context['cl'].filter_specs
                                       if getattr(f, 'field_path', None) == 'published_at')
                    for _, params in date_filter.links:
                        with CaptureQueriesContext(connection) as queries:
                            result = self.client.get(reverse('admin:core_announcement_changelist'),
                                                     {**params, '_facets': '1'})
                        self.assertEqual(result.status_code, 200)
                        expected = list(model_admin.get_queryset(result.wsgi_request)
                                        .filter(**params).values_list('pk', flat=True))
                        self.assertEqual([obj.pk for obj in result.context['cl'].result_list], expected)
                        self.assert_no_timezone_sql(queries)
                        if params.get('published_at__gte') == midnight and params.get('published_at__lt') == midnight + timedelta(days=1):
                            self.assertEqual(len(expected), 2)

    def test_publication_boundary_and_local_display(self):
        now = datetime(2025, 12, 31, 21, 30, tzinfo=dt_timezone.utc)
        due = Announcement.objects.create(title='Due', text='Text', is_published=True, published_at=now)
        Announcement.objects.create(title='Future', text='Text', is_published=True,
                                    published_at=now + timedelta(microseconds=1))
        with timezone.override('Europe/Moscow'), patch('core.views.timezone.now', return_value=now):
            for name in ('core:home', 'core:news'):
                with self.subTest(page=name), CaptureQueriesContext(connection) as queries:
                    response = self.client.get(reverse(name))
                self.assertEqual(response.status_code, 200)
                self.assertContains(response, 'Due')
                self.assertNotContains(response, 'Future')
                self.assertContains(response, '2026-01-01T00:30:00+03:00')
                self.assert_no_timezone_sql(queries)
        due.refresh_from_db()
        self.assertEqual(due.published_at, now)
